from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import binascii

def mix_string(*str_list):
    """將多個字串交錯混合成新字串"""
    res = ""
    max_len = max(len(s) for s in str_list)
    for n in range(max_len):
        for s in str_list:
            if len(s) > n:
                res += s[n]
    return res

def get_key_and_iv(key2, key1, key):
    """生成密鑰和初始化向量 (IV)"""
    mixed_key = mix_string(key2, key1)
    mixed_iv = mix_string(key2, key)[:16]  # IV 只取前 16 字節
    key_bytes = pad(mixed_key.encode('utf-8'), AES.block_size)
    iv_bytes = pad(mixed_iv.encode('utf-8'), AES.block_size)[:16]
    return key_bytes, iv_bytes

def decode_hex(hex_data, key2, key1, key):
    """解密十六進制加密資料"""
    encrypted_bytes = binascii.unhexlify(hex_data)
    key_bytes, iv_bytes = get_key_and_iv(key2, key1, key)
    cipher = AES.new(key_bytes, AES.MODE_CBC, iv_bytes)
    decrypted_bytes = unpad(cipher.decrypt(encrypted_bytes), AES.block_size)
    return decrypted_bytes.decode('utf-8')

# 示例用法
key2 = "4u5ytu78"
key1 = "j5d2xw92"
key = "56s2dut9"

# 加密的十六進制字串
hex_data = ""  # 替換成你的十六進制字串

try:
    decoded_text = decode_hex(hex_data, key2, key1, key)
    print("Decrypted text:", decoded_text)
except Exception as e:
    print("Decryption failed:", str(e))